using System;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.Data;
using Microsoft.SemanticKernel.Embeddings;
using Moq;
using Xunit;

namespace SemanticKernel.Core.Tests.Data.TextSearch
{
    public class TextSearchServiceCollectionExtensionsTests
    {
        [Fact]
        public void AddVectorStoreTextSearch_ShouldRegisterVectorStoreTextSearch()
        {
            // Arrange
            var serviceCollection = new ServiceCollection();
            var mockVectorSearchable = new Mock<IVectorSearchable<string>>();
            var mockStringMapper = new Mock<ITextSearchStringMapper>();
            var mockResultMapper = new Mock<ITextSearchResultMapper>();
            var options = new VectorStoreTextSearchOptions();

            serviceCollection.AddSingleton(mockVectorSearchable.Object);
            serviceCollection.AddSingleton(mockStringMapper.Object);
            serviceCollection.AddSingleton(mockResultMapper.Object);
            serviceCollection.AddSingleton(options);

            // Act
            serviceCollection.AddVectorStoreTextSearch<string>();

            // Assert
            var serviceProvider = serviceCollection.BuildServiceProvider();
            var vectorStoreTextSearch = serviceProvider.GetService<VectorStoreTextSearch<string>>();

            Assert.NotNull(vectorStoreTextSearch);
        }

        [Fact]
        public void AddVectorStoreTextSearch_ShouldThrowInvalidOperationException_WhenNoIVectorSearchableRegistered()
        {
            // Arrange
            var serviceCollection = new ServiceCollection();
            var mockStringMapper = new Mock<ITextSearchStringMapper>();
            var mockResultMapper = new Mock<ITextSearchResultMapper>();
            var options = new VectorStoreTextSearchOptions();

            serviceCollection.AddSingleton(mockStringMapper.Object);
            serviceCollection.AddSingleton(mockResultMapper.Object);
            serviceCollection.AddSingleton(options);

            // Act & Assert
            var exception = Assert.Throws<InvalidOperationException>(() => serviceCollection.AddVectorStoreTextSearch<string>());
            Assert.Equal("No IVectorSearch<TRecord> registered.", exception.Message);
        }

        [Fact]
        public void AddVectorStoreTextSearch_WithServiceId_ShouldRegisterVectorStoreTextSearch()
        {
            // Arrange
            var serviceCollection = new ServiceCollection();
            var mockVectorSearchable = new Mock<IVectorSearchable<string>>();
            var mockStringMapper = new Mock<ITextSearchStringMapper>();
            var mockResultMapper = new Mock<ITextSearchResultMapper>();
            var options = new VectorStoreTextSearchOptions();
            const string serviceId = "TestServiceId";

            serviceCollection.AddKeyedSingleton<IVectorSearchable<string>>(serviceId, mockVectorSearchable.Object);
            serviceCollection.AddSingleton(mockStringMapper.Object);
            serviceCollection.AddSingleton(mockResultMapper.Object);
            serviceCollection.AddSingleton(options);

            // Act
            serviceCollection.AddVectorStoreTextSearch<string>(serviceId);

            // Assert
            var serviceProvider = serviceCollection.BuildServiceProvider();
            var vectorStoreTextSearch = serviceProvider.GetKeyedService<VectorStoreTextSearch<string>>(serviceId);

            Assert.NotNull(vectorStoreTextSearch);
        }

        [Fact]
        public void AddVectorStoreTextSearch_WithServiceId_ShouldThrowInvalidOperationException_WhenNoIVectorSearchableRegistered()
        {
            // Arrange
            var serviceCollection = new ServiceCollection();
            var mockStringMapper = new Mock<ITextSearchStringMapper>();
            var mockResultMapper = new Mock<ITextSearchResultMapper>();
            var options = new VectorStoreTextSearchOptions();
            const string serviceId = "TestServiceId";

            serviceCollection.AddSingleton(mockStringMapper.Object);
            serviceCollection.AddSingleton(mockResultMapper.Object);
            serviceCollection.AddSingleton(options);

            // Act & Assert
            var exception = Assert.Throws<InvalidOperationException>(() => serviceCollection.AddVectorStoreTextSearch<string>(serviceId));
            Assert.Equal($"No IVectorSearch<TRecord> for service id {serviceId} registered.", exception.Message);
        }
    }
}
